</script>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #0b1020; font-family: 'Segoe UI', system-ui, sans-serif; }
  #wrap { position: relative; width: 100vw; height: 100vh; display: flex; align-items: center; justify-content: center; }
  #stage { position: relative; width: 100%; max-width: 1280px; aspect-ratio: 16/9; background: #0f172a; border-radius: 12px; overflow: hidden; box-shadow: 0 20px 60px rgba(0,0,0,.6); }
  canvas { display: block; width: 100%; height: 100%; }
  .overlay { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 4%; color: #e2e8f0; background: radial-gradient(circle at 50% 30%, rgba(49,46,129,.92), rgba(15,23,42,.97)); z-index: 10; }
  .overlay h1 { font-size: clamp(20px, 4.2vw, 44px); margin-bottom: 2%; background: linear-gradient(90deg,#67e8f9,#a78bfa); -webkit-background-clip: text; background-clip: text; color: transparent; }
  .overlay p { font-size: clamp(12px, 1.8vw, 18px); max-width: 80%; margin-bottom: 3%; line-height: 1.5; opacity: .92; }
  .btn { cursor: pointer; border: none; padding: 2.2% 5%; font-size: clamp(13px, 2vw, 20px); font-weight: 700; color: #0b1020; background: linear-gradient(135deg,#67e8f9,#a78bfa); border-radius: 999px; box-shadow: 0 8px 24px rgba(103,232,249,.35); transition: transform .15s; }
  .btn:active { transform: scale(.95); }
  .wm { position: absolute; bottom: 2.5%; font-size: clamp(9px, 1.3vw, 13px); opacity: .55; letter-spacing: .5px; }
  .wm b { color: #67e8f9; }
  #muteBtn { position: absolute; top: 2.5%; right: 2.5%; z-index: 20; cursor: pointer; border: 1px solid rgba(255,255,255,.25); background: rgba(15,23,42,.6); color: #e2e8f0; border-radius: 10px; padding: 6px 10px; font-size: clamp(11px,1.5vw,15px); }
  #touch { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
  .tbtn { position: absolute; bottom: 4%; width: 15%; aspect-ratio: 1; max-width: 90px; border-radius: 50%; background: rgba(103,232,249,.18); border: 2px solid rgba(103,232,249,.5); color: #e2e8f0; font-size: clamp(18px,3vw,30px); display: flex; align-items: center; justify-content: center; pointer-events: auto; user-select: none; -webkit-user-select: none; touch-action: none; }
  .tbtn:active { background: rgba(103,232,249,.4); }
  #tLeft { left: 4%; } #tRight { left: 22%; } #tJump { right: 4%; }
  .hidden { display: none !important; }
</style>
</head>
<body>
<div id="wrap">
  <div id="stage">
    <canvas id="cv" width="1280" height="720"></canvas>

    <div id="startScreen" class="overlay">
      <h1>Gravitasi Rani</h1>
      <p>Lompat ke platform yang cocok dengan jenis energi yang diminta!<br>Kumpulkan 10 platform benar untuk mengembalikan reaktor.</p>
      <button class="btn" id="startBtn">Mulai Bermain</button>
      <div class="wm">Built with <b>AISYS HTML5 Engine</b> · STIKOM YOS SUDARSO</div>
    </div>

    <div id="endScreen" class="overlay hidden">
      <h1 id="endTitle">Selesai</h1>
      <p id="endMsg"></p>
      <button class="btn" id="againBtn">Main Lagi</button>
      <div class="wm">Built with <b>AISYS HTML5 Engine</b> · STIKOM YOS SUDARSO</div>
    </div>

    <button id="muteBtn">🔊 Suara</button>

    <div id="touch" class="hidden">
      <div class="tbtn" id="tLeft">◀</div>
      <div class="tbtn" id="tRight">▶</div>
      <div class="tbtn" id="tJump">⤒</div>
    </div>
  </div>
</div>

<script>
(function(){
  const cv = document.getElementById('cv');
  const ctx = cv.getContext('2d');
  const W = 1280, H = 720;

  // ---------- AUDIO ----------
  let audioCtx = null, muted = false;
  function unlockAudio(){ if(!audioCtx){ try{ audioCtx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } if(audioCtx && audioCtx.state==='suspended') audioCtx.resume(); }
  function beep(freq, dur, type, vol){
    if(muted || !audioCtx) return;
    const o = audioCtx.createOscillator(), g = audioCtx.createGain();
    o.type = type||'sine'; o.frequency.value = freq;
    g.gain.setValueAtTime(vol||0.12, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
    o.connect(g); g.connect(audioCtx.destination);
    o.start(); o.stop(audioCtx.currentTime + dur);
  }
  const sfx = {
    jump(){ beep(520,0.12,'square',0.08); },
    good(){ beep(660,0.1,'sine',0.12); setTimeout(()=>beep(880,0.12,'sine',0.12),90); },
    bad(){ beep(180,0.22,'sawtooth',0.1); },
    win(){ [523,659,784,1046].forEach((f,i)=>setTimeout(()=>beep(f,0.18,'sine',0.12), i*130)); },
    lose(){ [400,320,240].forEach((f,i)=>setTimeout(()=>beep(f,0.22,'sawtooth',0.1), i*150)); }
  };
  document.getElementById('muteBtn').addEventListener('click', function(){
    unlockAudio(); muted = !muted;
    this.textContent = muted ? '🔇 Bisu' : '🔊 Suara';
  });

  // ---------- GAME STATE ----------
  const G = {
    running:false, over:false, score:0, correct:0, target:10, lives:3,
    camX:0, time:0, particles:[], floaters:[], shake:0,
    targetType:'kinetic', // 'kinetic' | 'potential'
    platforms:[], player:null, keys:{}, msgTimer:0, msg:''
  };

  const GRAV = 2200, MOVE = 420, JUMP = 950;
  const TYPES = {
    kinetic:   { label:'Energi Kinetik',   color:'#67e8f9', glow:'#22d3ee', hint:'benda bergerak' },
    potential: { label:'Energi Potensial', color:'#a78bfa', glow:'#8b5cf6', hint:'benda di ketinggian' }
  };

  // ---------- LEVEL GENERATION ----------
  function makePlatforms(){
    const arr = [];
    // ground start
    arr.push({ x:0, y:600, w:520, h:120, type:'ground' });
    let x = 620;
    const types = ['kinetic','potential'];
    for(let i=0;i<40;i++){
      const t = types[Math.floor(Math.random()*2)];
      const w = 150 + Math.random()*90;
      const y = 380 + Math.random()*180; // 380..560
      arr.push({ x:x, y:y, w:w, h:26, type:t, collected:false, bob:Math.random()*6.28 });
      x += w + 130 + Math.random()*90;
    }
    // final ground
    arr.push({ x:x, y:600, w:600, h:120, type:'ground' });
    return arr;
  }

  function resetGame(){
    G.running = true; G.over = false; G.score = 0; G.correct = 0; G.lives = 3;
    G.camX = 0; G.time = 0; G.particles = []; G.floaters = []; G.shake = 0;
    G.platforms = makePlatforms();
    G.player = { x:120, y:520, vx:0, vy:0, w:44, h:56, onGround:false, face:1, invuln:0 };
    G.targetType = 'kinetic'; G.msgTimer = 0; G.msg = '';
    pickTarget();
  }

  function pickTarget(){
    // alternate-ish with some randomness
    G.targetType = Math.random() < 0.5 ? 'kinetic' : 'potential';
  }

  // ---------- INPUT ----------
  window.addEventListener('keydown', e=>{
    if(['ArrowLeft','ArrowRight','ArrowUp',' ','a','d','w','A','D','W'].includes(e.key)) e.preventDefault();
    G.keys[e.key.toLowerCase()] = true;
    if((e.key===' '||e.key==='ArrowUp'||e.key.toLowerCase()==='w') && G.running) tryJump();
  });
  window.addEventListener('keyup', e=>{ G.keys[e.key.toLowerCase()] = false; });

  function bindTouch(id, key){
    const el = document.getElementById(id);
    const on = e=>{ e.preventDefault(); unlockAudio(); G.keys[key]=true; if(key==='jump') tryJump(); };
    const off = e=>{ e.preventDefault(); G.keys[key]=false; };
    el.addEventListener('touchstart', on, {passive:false});
    el.addEventListener('touchend', off, {passive:false});
    el.addEventListener('touchcancel', off, {passive:false});
    el.addEventListener('mousedown', on);
    el.addEventListener('mouseup', off);
    el.addEventListener('mouseleave', off);
  }
  bindTouch('tLeft','arrowleft');
  bindTouch('tRight','arrowright');
  bindTouch('tJump','jump');

  function tryJump(){
    const p = G.player;
    if(p && p.onGround){ p.vy = -JUMP; p.onGround = false; sfx.jump(); }
  }

  // ---------- UPDATE ----------
  function update(dt){
    if(!G.running || G.over) return;
    G.time += dt;
    const p = G.player;

    // horizontal input
    let dir = 0;
    if(G.keys['arrowleft']||G.keys['a']) dir -= 1;
    if(G.keys['arrowright']||G.keys['d']) dir += 1;
    p.vx = dir * MOVE;
    if(dir!==0) p.face = dir;

    // gravity
    p.vy += GRAV * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    if(p.invuln>0) p.invuln -= dt;

    // world bounds
    if(p.x < 0) p.x = 0;

    // collision with platforms (only land from above)
    p.onGround = false;
    for(const pl of G.platforms){
      if(p.x + p.w > pl.x && p.x < pl.x + pl.w){
        const prevBottom = p.y + p.h - p.vy*dt;
        if(p.vy >= 0 && prevBottom <= pl.y + 8 && p.y + p.h >= pl.y && p.y + p.h <= pl.y + pl.h + 20){
          p.y = pl.y - p.h;
          p.vy = 0;
          p.onGround = true;
          // collect if labeled platform
          if(pl.type!=='ground' && !pl.collected){
            pl.collected = true;
            handleCollect(pl);
          }
        }
      }
    }

    // fall off world
    if(p.y > H + 200){
      loseLife(true);
    }

    // camera follow
    const targetCam = Math.max(0, p.x - W*0.35);
    G.camX += (targetCam - G.camX) * Math.min(1, dt*6);

    // particles
    for(let i=G.particles.length-1;i>=0;i--){
      const pt = G.particles[i];
      pt.x += pt.vx*dt; pt.y += pt.vy*dt; pt.vy += 600*dt; pt.life -= dt;
      if(pt.life<=0) G.particles.splice(i,1);
    }
    for(let i=G.floaters.length-1;i>=0;i--){
      const f = G.floaters[i]; f.y -= 40*dt; f.life -= dt;
      if(f.life<=0) G.floaters.splice(i,1);
    }
    if(G.shake>0) G.shake = Math.max(0, G.shake - dt*40);
    if(G.msgTimer>0) G.msgTimer -= dt;
  }

  function handleCollect(pl){
    const p = G.player;
    if(pl.type === G.targetType){
      G.correct++; G.score += 100;
      sfx.good();
      burst(pl.x+pl.w/2, pl.y, TYPES[pl.type].glow, 18);
      floatText(pl.x+pl.w/2, pl.y-20, '+100 '+TYPES[pl.type].label, '#67e8f9');
      G.msg = 'Benar! '+TYPES[pl.type].label+' karena '+TYPES[pl.type].hint+'.';
      G.msgTimer = 2.2;
      if(G.correct >= G.target){ winGame(); return; }
      pickTarget();
    } else {
      G.score = Math.max(0, G.score - 40);
      sfx.bad();
      burst(pl.x+pl.w/2, pl.y, '#ef4444', 14);
      floatText(pl.x+pl.w/2, pl.y-20, '-40 salah jenis', '#f87171');
      G.msg = 'Ups! Itu '+TYPES[pl.type].label+', bukan '+TYPES[G.targetType].label+'.';
      G.msgTimer = 2.4;
      G.shake = 10;
    }
  }

  function loseLife(fell){
    const p = G.player;
    if(p.invuln>0 && !fell) return;
    G.lives--;
    sfx.bad();
    G.shake = 14;
    if(G.lives <= 0){ loseGame(); return; }
    // respawn at nearest safe platform start
    p.x = Math.max(0, p.x - 60);
    p.y = 200; p.vy = 0; p.invuln = 1.5;
    G.msg = fell ? 'Jatuh! Hati-hati ya.' : 'Aduh!';
    G.msgTimer = 1.6;
  }

  function burst(x,y,color,n){
    for(let i=0;i<n;i++){
      const a = Math.random()*Math.PI*2, s = 80+Math.random()*220;
      G.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-100,life:0.6+Math.random()*0.4,color,r:2+Math.random()*3});
    }
  }
  function floatText(x,y,text,color){
    G.floaters.push({x,y,text,color,life:1.4});
  }

  function winGame(){
    G.over = true; G.running = false; sfx.win();
    if(window.AISYS && AISYS.end) AISYS.end('menang');
    showEnd(true);
  }
  function loseGame(){
    G.over = true; G.running = false; sfx.lose();
    if(window.AISYS && AISYS.end) AISYS.end('kalah');
    showEnd(false);
  }

  // ---------- DRAW ----------
  function roundRect(x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath();
  }

  function drawBackground(){
    const g = ctx.createLinearGradient(0,0,0,H);
    g.addColorStop(0,'#1e1b4b'); g.addColorStop(0.5,'#312e81'); g.addColorStop(1,'#0f766e');
    ctx.fillStyle = g; ctx.fillRect(0,0,W,H);

    // soft glow blobs
    for(let i=0;i<5;i++){
      const bx = ((i*300 - G.camX*0.15)%(W+400))-200;
      const by = 120 + i*90;
      const rg = ctx.createRadialGradient(bx,by,0,bx,by,180);
      rg.addColorStop(0,'rgba(103,232,249,0.10)'); rg.addColorStop(1,'rgba(103,232,249,0)');
      ctx.fillStyle = rg; ctx.beginPath(); ctx.arc(bx,by,180,0,6.28); ctx.fill();
    }

    // lab pillars parallax
    ctx.fillStyle = 'rgba(148,163,184,0.10)';
    for(let i=0;i<10;i++){
      const px = ((i*220 - G.camX*0.35)%(W+300))-150;
      ctx.fillRect(px, 200, 60, 420);
    }
    // floor grid
    ctx.strokeStyle = 'rgba(103,232,249,0.08)'; ctx.lineWidth = 1;
    for(let i=0;i<20;i++){
      const gx = ((i*80 - G.camX*0.6)%(W+80))-40;
      ctx.beginPath(); ctx.moveTo(gx,0); ctx.lineTo(gx,H); ctx.stroke();
    }
  }

  function drawPlatforms(){
    for(const pl of G.platforms){
      const sx = pl.x - G.camX;
      if(sx + pl.w < -50 || sx > W+50) continue;
      if(pl.type==='ground'){
        const g = ctx.createLinearGradient(0,pl.y,0,pl.y+pl.h);
        g.addColorStop(0,'#334155'); g.addColorStop(1,'#1e293b');
        ctx.fillStyle = g; roundRect(sx,pl.y,pl.w,pl.h,10); ctx.fill();
        ctx.strokeStyle = 'rgba(103,232,249,0.35)'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(sx,pl.y); ctx.lineTo(sx+pl.w,pl.y); ctx.stroke();
      } else {
        const t = TYPES[pl.type];
        const bob = Math.sin(G.time*2 + pl.bob)*3;
        const py = pl.y + bob;
        if(pl.collected){
          ctx.globalAlpha = 0.35;
        }
        ctx.shadowColor = t.glow; ctx.shadowBlur = 18;
        const g = ctx.createLinearGradient(0,py,0,py+pl.h);
        g.addColorStop(0,t.color); g.addColorStop(1,t.glow);
        ctx.fillStyle = g; roundRect(sx,py,pl.w,pl.h,12); ctx.fill();
        ctx.shadowBlur = 0;
        // label
        ctx.fillStyle = 'rgba(15,23,42,0.9)';
        ctx.font = 'bold 15px Segoe UI, sans-serif';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(t.label, sx+pl.w/2, py+pl.h/2);
        ctx.globalAlpha = 1;
      }
    }
  }

  function drawPlayer(){
    const p = G.player;
    const sx = p.x - G.camX;
    if(p.invuln>0 && Math.floor(G.time*12)%2===0) return;
    ctx.save();
    ctx.translate(sx + p.w/2, p.y + p.h/2);
    // glow aura
    const rg = ctx.createRadialGradient(0,0,0,0,0,50);
    rg.addColorStop(0,'rgba(167,139,250,0.5)'); rg.addColorStop(1,'rgba(167,139,250,0)');
    ctx.fillStyle = rg; ctx.beginPath(); ctx.arc(0,0,50,0,6.28); ctx.fill();
    // body
    const g = ctx.createLinearGradient(0,-p.h/2,0,p.h/2);
    g.addColorStop(0,'#c4b5fd'); g.addColorStop(1,'#7c3aed');
    ctx.fillStyle = g;
    roundRect(-p.w/2, -p.h/2, p.w, p.h, 12); ctx.fill();
    // head
    ctx.fillStyle = '#fde68a'; ctx.beginPath(); ctx.arc(0,-p.h/2-6,14,0,6.28); ctx.fill();
    // eyes
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.arc(-4*p.face,-p.h/2-8,2.5,0,6.28); ctx.fill();
    ctx.beginPath(); ctx.arc(4*p.face,-p.h/2-8,2.5,0,6.28); ctx.fill();
    // smile
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(0,-p.h/2-2,4,0.2,Math.PI-0.2); ctx.stroke();
    ctx.restore();
  }

  function drawParticles(){
    for(const pt of G.particles){
      ctx.globalAlpha = Math.max(0, pt.life);
      ctx.fillStyle = pt.color;
      ctx.beginPath(); ctx.arc(pt.x-G.camX, pt.y, pt.r, 0, 6.28); ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'center'; ctx.font = 'bold 18px Segoe UI, sans-serif';
    for(const f of G.floaters){
      ctx.globalAlpha = Math.max(0, f.life/1.4);
      ctx.fillStyle = f.color;
      ctx.fillText(f.text, f.x-G.camX, f.y);
    }
    ctx.globalAlpha = 1;
  }

  function drawHUD(){
    // top bar
    ctx.fillStyle = 'rgba(15,23,42,0.72)';
    roundRect(20,20,360,86,16); ctx.fill();

    ctx.textAlign = 'left'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 18px Segoe UI, sans-serif';
    ctx.fillText('Skor: '+G.score, 40, 46);

    // lives
    ctx.fillText('Nyawa:', 40, 80);
    for(let i=0;i<3;i++){
      ctx.fillStyle = i < G.lives ? '#f472b6' : 'rgba(148,163,184,0.3)';
      ctx.beginPath(); ctx.arc(120 + i*26, 80, 9, 0, 6.28); ctx.fill();
    }

    // target panel
    const t = TYPES[G.targetType];
    const pw = 420;
    const px = W - pw - 20;
    ctx.fillStyle = 'rgba(15,23,42,0.78)';
    roundRect(px,20,pw,86,16); ctx.fill();
    ctx.strokeStyle = t.color; ctx.lineWidth = 2;
    roundRect(px,20,pw,86,16); ctx.stroke();

    ctx.fillStyle = '#94a3b8'; ctx.font = 'bold 14px Segoe UI, sans-serif';
    ctx.fillText('LOMPAT KE PLATFORM:', px+20, 42);
    ctx.fillStyle = t.color; ctx.font = 'bold 24px Segoe UI, sans-serif';
    ctx.fillText(t.label, px+20, 72);
    ctx.fillStyle = '#cbd5e1'; ctx.font = '13px Segoe UI, sans-serif';
    ctx.fillText('('+t.hint+')', px+20, 94);

    // progress
    ctx.fillStyle = 'rgba(15,23,42,0.72)';
    roundRect(W/2-160, 20, 320, 40, 12); ctx.fill();
    ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 15px Segoe UI, sans-serif'; ctx.textAlign='center';
    ctx.fillText('Reaktor: '+G.correct+' / '+G.target, W/2, 40);
    // bar
    ctx.fillStyle = 'rgba(148,163,184,0.25)';
    roundRect(W/2-140, 48, 280, 8, 4); ctx.fill();
    ctx.fillStyle = '#67e8f9';
    roundRect(W/2-140, 48, 280*(G.correct/G.target), 8, 4); ctx.fill();

    // message
    if(G.msgTimer>0 && G.msg){
      ctx.globalAlpha = Math.min(1, G.msgTimer);
      ctx.fillStyle = 'rgba(15,23,42,0.85)';
      const mw = ctx.measureText(G.msg).width + 60;
      roundRect(W/2-mw/2, H-110, mw, 46, 14); ctx.fill();
      ctx.fillStyle = '#e2e8f0'; ctx.font = 'bold 16px Segoe UI, sans-serif'; ctx.textAlign='center';
      ctx.fillText(G.msg, W/2, H-87);
      ctx.globalAlpha = 1;
    }

    // watermark
    ctx.fillStyle = 'rgba(255,255,255,0.35)'; ctx.font = '12px Segoe UI, sans-serif'; ctx.textAlign='right';
    ctx.fillText('AISYS HTML5 Engine', W-20, H-16);
  }

  function render(){
    ctx.save();
    if(G.shake>0){
      ctx.translate((Math.random()-0.5)*G.shake, (Math.random()-0.5)*G.shake);
    }
    drawBackground();
    drawPlatforms();
    if(G.player) drawPlayer();
    drawParticles();
    ctx.restore();
    drawHUD();
  }

  // ---------- LOOP ----------
  let last = performance.now();
  function loop(now){
    const dt = Math.min(0.033, (now-last)/1000);
    last = now;
    update(dt);
    render();
    requestAnimationFrame(loop);
  }

  // ---------- SCREENS ----------
  const startScreen = document.getElementById('startScreen');
  const endScreen = document.getElementById('endScreen');
  const endTitle = document.getElementById('endTitle');
  const endMsg = document.getElementById('endMsg');
  const touch = document.getElementById('touch');

  function showEnd(win){
    endTitle.textContent = win ? '🏆 Reaktor Kembali!' : '💫 Coba Lagi!';
    endMsg.textContent = win
      ? 'Profesor Entropi menyerah dan mereka berbaikan. Skor akhir: '+G.score
      : 'Lab gelap, tapi Rani tak menyerah belajar. Skor: '+G.score;
    endScreen.classList.remove('hidden');
  }

  document.getElementById('startBtn').addEventListener('click', ()=>{
    unlockAudio();
    startScreen.classList.add('hidden');
    touch.classList.remove('hidden');
    resetGame();
  });
  document.getElementById('againBtn').addEventListener('click', ()=>{
    endScreen.classList.add('hidden');
    resetGame();
  });

  // init preview
  resetGame();
  G.running = false;
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
<!-- END_OF_GAME -->
